import { types } from '@jbrowse/mobx-state-tree'

import { maxInlineSnapshotBytes } from '../constants.ts'

/**
 * #stateModel DataModel
 * the data stored for the model. this is sometimes temporary in the case that
 * e.g. msaFilehandle is available on the parent model, because then the msa
 * data will not be persisted in saved session snapshots, it will be fetched
 * from msaFilehandle at startup
 */
export function DataModelF(maxInlineBytes = maxInlineSnapshotBytes) {
  return types
    .model({
      /**
       * #property
       */
      tree: types.maybe(types.string),
      /**
       * #property
       */
      msa: types.maybe(types.string),
      /**
       * #property
       */
      treeMetadata: types.maybe(types.string),
      /**
       * #property
       */
      gff: types.maybe(types.string),
    })
    .actions(self => ({
      /**
       * #action
       */
      setTree(tree?: string) {
        self.tree = tree
      },
      /**
       * #action
       */
      setMSA(msa?: string) {
        self.msa = msa
      },
      /**
       * #action
       */
      setTreeMetadata(treeMetadata?: string) {
        self.treeMetadata = treeMetadata
      },
      /**
       * #action
       */
      setGFF(gff?: string) {
        self.gff = gff
      },
    }))
    .postProcessSnapshot(snap =>
      // drops any field over maxInlineBytes; the parent model's
      // `unshareableData` reports what was dropped
      Object.fromEntries(
        Object.entries(snap).map(([key, text]) => [
          key,
          text && text.length > maxInlineBytes ? undefined : text,
        ]),
      ),
    )
}
